// DEMO SOURCE. Replace with your no-show log (Google Sheet).
// Columns: appointment_id, customer_name, phone, missed_at (ISO), treatment, fee_eur, prior_no_shows
const demoRows = [
  {
    appointment_id: 'APT-4001',
    customer_name: 'Kevin Voorbeeld',
    phone: '+316****5631',
    missed_at: new Date(Date.now() - 24 * 3600 * 1000).toISOString(),
    treatment: 'Haircut',
    fee_eur: 25,
    prior_no_shows: 0
  },
  {
    appointment_id: 'APT-4002',
    customer_name: 'Bram Voorbeeld',
    phone: '+316****5632',
    missed_at: new Date(Date.now() - 26 * 3600 * 1000).toISOString(),
    treatment: 'Balayage',
    fee_eur: 45,
    prior_no_shows: 2
  }
];
return demoRows.map((row) => ({ json: row }));

// Prepare rows: parse the missed timestamp once and compute hoursAgo,
// so the window check downstream is a simple branch. Rows with a broken
// or missing timestamp or contact are flagged with the exact reason and
// routed to the error log.
const items = $input.all();
const now = Date.now();
const out = [];
for (const item of items) {
  const r = item.json;
  const t = r.missed_at ? new Date(r.missed_at).getTime() : NaN;
  let rowError = null;
  if (!r.appointment_id) rowError = 'missing appointment_id';
  else if (!r.phone) rowError = 'missing phone';
  else if (isNaN(t)) rowError = 'missed_at not parseable';
  out.push({
    json: {
      ...r,
      hours_ago: rowError ? null : (now - t) / 3600000,
      row_valid: !rowError,
      row_error: rowError
    }
  });
}
return out;

// Error path: rows with a missing appointment_id, phone, or an unparseable
// missed_at land here instead of silently vanishing, carrying the exact
// reason set by the prepare node. In production, write these to a
// 'dunning_errors' sheet so a human can fix the source data.
const items = $input.all();
return items.map((item) => ({
  json: {
    error: 'invalid no-show row',
    appointment_id: item.json.appointment_id || null,
    reason: item.json.row_error || 'unknown',
    seen_at: new Date().toISOString()
  }
}));

// Rows outside the 20-30h dunning window pass by harmlessly. They stay in
// the sheet; the next run picks them up when their time comes.
const items = $input.all();
return items.map((item) => ({
  json: {
    skipped: true,
    appointment_id: item.json.appointment_id,
    hours_ago: item.json.hours_ago,
    skipped_at: new Date().toISOString()
  }
}));

// Escalation ladder, run only on rows inside the 20-30h window:
//   first no-show  -> friendly invoice with fee, easy online payment link
//   repeat (2+)    -> fee + prepay requirement for future bookings
// Skip rules before anything is built: rows the reply arm already closed
// (recovered / partial_paid / disputed in workflow static data) never get
// another message, and a send log keeps each tier to ONE message per
// appointment even if the schedule fires twice inside the window.
const store = $getWorkflowStaticData('global');
store.recovery_state = store.recovery_state || {};
store.dunning_sent = store.dunning_sent || {};
const cutoff = Date.now() - 60 * 24 * 3600 * 1000;
for (const k of Object.keys(store.dunning_sent)) {
  if ((store.dunning_sent[k].at || 0) < cutoff) delete store.dunning_sent[k];
}
const items = $input.all();
const out = [];
for (const item of items) {
  const r = item.json;
  const closed = store.recovery_state[r.appointment_id];
  if (closed && ['recovered', 'partial_paid', 'disputed'].includes(closed.status)) {
    continue; // reply webhook already closed this case
  }
  const repeat = (r.prior_no_shows || 0) >= 2;
  const tier = repeat ? 'repeat_offender' : 'first_offense';
  const key = r.appointment_id + ':' + tier;
  if (store.dunning_sent[key]) continue; // this tier already sent
  let message;
  if (repeat) {
    message = 'Hi ' + r.customer_name + ', we missed you at your last appointment. Your no-show fee of EUR ' + r.fee_eur + ' is ready to pay: PAYMENTLINK. For new bookings we now ask a small deposit to hold the time. We would love to see you again.';
  } else {
    message = 'Hi ' + r.customer_name + ', we missed you. No problem, it happens. We do charge EUR ' + r.fee_eur + ' for the reserved time block: PAYMENTLINK. Want to pick a new time? Reply NEW.';
  }
  store.dunning_sent[key] = { at: Date.now() };
  out.push({
    json: {
      appointment_id: r.appointment_id,
      customer_name: r.customer_name,
      to: r.phone,
      channel: 'whatsapp',
      tier: tier,
      fee_eur: r.fee_eur,
      message: message
    }
  });
}
return out;

// Placeholder for the send node (WhatsApp Business Cloud / SMS).
const items = $input.all();
return items.map((item) => ({
    json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo' }
}));

// Track fee recovery: every sent escalation is stamped here. Wire a
// Sheet write; the reply webhook in the second arm closes cases in
// static data (recovered / partial_paid / disputed).
const items = $input.all();
return items.map((item) => ({
    json: { ...item.json, tracked_at: new Date().toISOString(), recovery_state: 'awaiting_payment' }
}));

// Classify the customer's payment reply. One keyword is enough,
// case-insensitive, bilingual (EN + NL):
//   paid:     paid, payed, betaald, voldaan
//   partial:  partial, deelbetaling, gedeeltelijk, half
//   dispute:  dispute, betwist, contest, wrong, onjuist
// Anything else stays 'unknown' and gets the help text.
const KW = {
  // order matters: the most specific keyword wins, so a reply like
  // 'gedeeltelijk betaald' classifies as partial, not paid
  dispute: ['dispute', 'betwist', 'contest', 'wrong', 'onjuist'],
  partial: ['partial', 'deelbetaling', 'gedeeltelijk', 'half'],
  paid: ['paid', 'payed', 'betaald', 'voldaan'],
};
const MSG = {
  paid: 'Thank you, we received your payment and the case is closed.',
  partial: 'Thanks for the partial payment. We flagged the remainder for our team and will follow up shortly.',
  dispute: 'Got it, we put the fee on hold. Our team will review it and message you.',
  unknown: 'Thanks for the reply. Reply PAID once the fee is settled, or DISPUTE if something is wrong.',
};
const items = $input.all();
const out = [];
for (const item of items) {
  const b = item.json.body || item.json;
  const text = String(b.text || b.reply_text || '').toLowerCase();
  let verdict = 'unknown';
  for (const v of Object.keys(KW)) {
    if (KW[v].some((w) => text.includes(w))) { verdict = v; break; }
  }
  out.push({ json: {
    appointment_id: b.appointment_id,
    verdict: verdict,
    reply_text: text.slice(0, 200),
    message: MSG[verdict],
  } });
}
return out;

// Payment confirmed: close the case and stop the escalation ladder.
// Writes recovery_state in workflow static data (shared with the
// escalation arm): paid -> 'recovered', partial -> 'partial_paid' with a
// staff flag because the rest of the fee is still open.
const store = $getWorkflowStaticData('global');
store.recovery_state = store.recovery_state || {};
const items = $input.all();
const out = [];
for (const item of items) {
  const r = item.json;
  const status = r.verdict === 'partial' ? 'partial_paid' : 'recovered';
  store.recovery_state[r.appointment_id] = {
    status: status,
    at: new Date().toISOString(),
    via: 'reply webhook',
  };
  out.push({ json: {
    appointment_id: r.appointment_id,
    outcome: status,
    needs_staff: r.verdict === 'partial',
    recovered_at: new Date().toISOString(),
    verdict: r.verdict,
    message: r.message,
  } });
}
return out;

// Dispute: freeze the ladder and raise a staff task.
// Writes status 'disputed' so the escalation arm skips this appointment
// until a human resolves it. Rows keep the reply text for context.
const store = $getWorkflowStaticData('global');
store.recovery_state = store.recovery_state || {};
const items = $input.all();
const out = [];
for (const item of items) {
  const r = item.json;
  store.recovery_state[r.appointment_id] = {
    status: 'disputed',
    at: new Date().toISOString(),
    via: 'reply webhook',
  };
  out.push({ json: {
    appointment_id: r.appointment_id,
    outcome: 'disputed',
    needs_staff: true,
    flagged_at: new Date().toISOString(),
    verdict: r.verdict,
    reply_text: r.reply_text,
    message: r.message,
  } });
}
return out;
